create table employee (emp_id bigint not null auto_increment, create_at datetime, email_id varchar(255), first_name varchar(255), last_name varchar(255), update_at datetime, primary key (emp_id)) engine=InnoDB;
create table firebase_token (id bigint not null auto_increment, create_at datetime, token varchar(255), update_at datetime, username bigint, primary key (id)) engine=InnoDB;
create table image (image_id bigint not null auto_increment, create_at datetime, resource_type varchar(255), secure_url varchar(255), update_at datetime, url varchar(255), primary key (image_id)) engine=InnoDB;
create table message (id id DEFAULT uuid_generate_v4() not null, created_at datetime, message varchar(255), message_type varchar(255), room varchar(255), username varchar(255), primary key (id)) engine=InnoDB;
create table rooms (room_id varchar(255) not null, connected_count integer, create_at datetime, update_at datetime, primary key (room_id)) engine=InnoDB;
